//! Typed JSON-RPC and Codex `app-server` messages.
//!
//! Shapes follow the schema generated by `codex app-server
//! generate-json-schema` for the pinned CLI version (`CODEX_VERSIONS`), and
//! only for the messages the first slice needs. The wire has no `jsonrpc`
//! member; it is neither sent nor required.
//!
//! Inbound lines are first read as an [`Envelope`] (ids, method, and raw
//! `params`/`result` slices borrowed from the line), classified by
//! [`Envelope::classify`], and only then decoded into the typed body for the
//! method. No message is built with `json!` or traversed as an untyped value.

use std::collections::BTreeMap;

use omp_core::Str;
use serde::{Deserialize, Serialize, de::IgnoredAny};
use serde_json::value::RawValue;

// ---------------------------------------------------------------------------
// JSON-RPC envelope
// ---------------------------------------------------------------------------

/// A JSON-RPC request id: the wire allows a string or an integer.
#[derive(Clone, Debug, Deserialize, Eq, Hash, PartialEq, Serialize)]
#[serde(untagged)]
pub(crate) enum RequestId {
	/// Integer id; every id this client issues is one.
	Int(i64),
	/// Text id, as a server may choose for its own requests.
	Text(Str),
}

/// The `error` member of a JSON-RPC error response.
#[derive(Clone, Debug, Deserialize, Eq, PartialEq)]
pub(crate) struct RpcError {
	/// JSON-RPC error code.
	pub(crate) code: i64,
}

/// Every member a JSON-RPC line may carry, borrowed from the line.
#[derive(Debug, Deserialize)]
pub(crate) struct Envelope<'a> {
	#[serde(default)]
	id:     Option<RequestId>,
	#[serde(default)]
	method: Option<Str>,
	#[serde(default, borrow)]
	params: Option<&'a RawValue>,
	#[serde(default, borrow)]
	result: Option<&'a RawValue>,
	#[serde(default)]
	error:  Option<RpcError>,
}

/// An inbound line, classified.
#[derive(Debug)]
pub(crate) enum JsonRpcMessage<'a> {
	/// The server asks the client something and waits for a response.
	Request {
		/// Id to echo in the response.
		id:     RequestId,
		/// Method name.
		method: Str,
		/// Raw params.
		params: Option<&'a RawValue>,
	},
	/// The server reports something; no response is expected.
	Notification {
		/// Method name.
		method: Str,
		/// Raw params.
		params: Option<&'a RawValue>,
	},
	/// A successful response to a client request.
	Response {
		/// The id of the request.
		id:     RequestId,
		/// Raw result.
		result: &'a RawValue,
	},
	/// An error response to a client request.
	Error {
		/// The id of the request.
		id:    RequestId,
		/// The error.
		error: RpcError,
	},
}

impl<'a> Envelope<'a> {
	/// Classifies the envelope, or `None` when it fits no JSON-RPC shape.
	pub(crate) fn classify(self) -> Option<JsonRpcMessage<'a>> {
		match self {
			Self { id: Some(id), method: Some(method), params, .. } => {
				Some(JsonRpcMessage::Request { id, method, params })
			},
			Self { id: None, method: Some(method), params, .. } => {
				Some(JsonRpcMessage::Notification { method, params })
			},
			Self { id: Some(id), result: Some(result), .. } => {
				Some(JsonRpcMessage::Response { id, result })
			},
			Self { id: Some(id), error: Some(error), .. } => Some(JsonRpcMessage::Error { id, error }),
			_ => None,
		}
	}
}

/// A client request line.
#[derive(Serialize)]
pub(crate) struct OutRequest<'a, P> {
	/// Request id.
	pub(crate) id:     i64,
	/// Method name.
	pub(crate) method: &'static str,
	/// Typed params.
	pub(crate) params: &'a P,
}

/// A client notification line without params.
#[derive(Serialize)]
pub(crate) struct OutNotification {
	/// Method name.
	pub(crate) method: &'static str,
}

/// A client response to a server request.
#[derive(Serialize)]
pub(crate) struct OutResponse<'a, R> {
	/// The id of the request being answered.
	pub(crate) id:     &'a RequestId,
	/// Typed result.
	pub(crate) result: &'a R,
}

/// A client error response to a server request.
#[derive(Serialize)]
pub(crate) struct OutError<'a> {
	/// The id of the request being refused.
	pub(crate) id:    &'a RequestId,
	/// The error.
	pub(crate) error: OutErrorBody,
}

/// Body of [`OutError`].
#[derive(Serialize)]
pub(crate) struct OutErrorBody {
	/// JSON-RPC error code.
	pub(crate) code:    i64,
	/// Static, secret-free message.
	pub(crate) message: &'static str,
}

/// JSON-RPC "method not found".
pub(crate) const METHOD_NOT_FOUND: i64 = -32601;

