/// Client request: `initialize`.
pub(crate) const INITIALIZE: &str = "initialize";
/// Client notification: `initialized`.
pub(crate) const INITIALIZED: &str = "initialized";
/// Client request: `thread/start`.
pub(crate) const THREAD_START: &str = "thread/start";
/// Client request: `thread/resume`.
pub(crate) const THREAD_RESUME: &str = "thread/resume";
/// Client request: `thread/inject_items`.
pub(crate) const THREAD_INJECT_ITEMS: &str = "thread/inject_items";
/// Client request: `turn/start`.
pub(crate) const TURN_START: &str = "turn/start";
/// Client request: `turn/interrupt`.
pub(crate) const TURN_INTERRUPT: &str = "turn/interrupt";

/// Every server-initiated method this adapter knows by name.
///
/// [`Method::Inert`] lists the notifications of the pinned CLI version that
/// carry nothing the normalized event model represents (account, plugin,
/// realtime, reasoning and similar traffic). A method that is not listed is
/// [`Method::Unknown`] and is a protocol failure, not a silent drop.
#[derive(Clone, Copy, Debug, Eq, PartialEq, strum::EnumString)]
pub(crate) enum Method {
	/// `turn/started`.
	#[strum(serialize = "turn/started")]
	TurnStarted,
	/// `turn/completed`.
	#[strum(serialize = "turn/completed")]
	TurnCompleted,
	/// `item/started`.
	#[strum(serialize = "item/started")]
	ItemStarted,
	/// `item/completed`.
	#[strum(serialize = "item/completed")]
	ItemCompleted,
	/// `item/agentMessage/delta`.
	#[strum(serialize = "item/agentMessage/delta")]
	AgentMessageDelta,
	/// `thread/tokenUsage/updated`.
	#[strum(serialize = "thread/tokenUsage/updated")]
	TokenUsageUpdated,
	/// `error`.
	#[strum(serialize = "error")]
	Error,
	/// `thread/closed`.
	#[strum(serialize = "thread/closed")]
	ThreadClosed,
	/// `serverRequest/resolved`.
	#[strum(serialize = "serverRequest/resolved")]
	ServerRequestResolved,
	/// `item/commandExecution/requestApproval`.
	#[strum(serialize = "item/commandExecution/requestApproval")]
	CommandApproval,
	/// `item/fileChange/requestApproval`.
	#[strum(serialize = "item/fileChange/requestApproval")]
	FileChangeApproval,
	/// `item/permissions/requestApproval`.
	#[strum(serialize = "item/permissions/requestApproval")]
	PermissionsApproval,
	/// `item/tool/requestUserInput`.
	#[strum(serialize = "item/tool/requestUserInput")]
	UserInput,
	/// `mcpServer/elicitation/request`.
	#[strum(serialize = "mcpServer/elicitation/request")]
	Elicitation,
	/// `item/tool/call`.
	#[strum(serialize = "item/tool/call")]
	DynamicToolCall,
	/// `applyPatchApproval` (legacy).
	#[strum(serialize = "applyPatchApproval")]
	LegacyPatchApproval,
	/// `execCommandApproval` (legacy).
	#[strum(serialize = "execCommandApproval")]
	LegacyExecApproval,
	/// A notification of the pinned version with no normalized meaning.
	#[strum(
		serialize = "account/gatewayOAuth/changed",
		serialize = "account/login/completed",
		serialize = "account/rateLimits/updated",
		serialize = "account/updated",
		serialize = "app/list/updated",
		serialize = "autoApprovalReview/strictReviewRequired",
		serialize = "command/exec/outputDelta",
		serialize = "configWarning",
		serialize = "deprecationNotice",
		serialize = "externalAgentConfig/import/completed",
		serialize = "externalAgentConfig/import/progress",
		serialize = "fs/changed",
		serialize = "fuzzyFileSearch/sessionCompleted",
		serialize = "fuzzyFileSearch/sessionUpdated",
		serialize = "guardianWarning",
		serialize = "hook/completed",
		serialize = "hook/started",
		serialize = "item/autoApprovalReview/completed",
		serialize = "item/autoApprovalReview/started",
		serialize = "item/commandExecution/outputDelta",
		serialize = "item/commandExecution/terminalInteraction",
		serialize = "item/fileChange/outputDelta",
		serialize = "item/fileChange/patchUpdated",
		serialize = "item/mcpToolCall/progress",
		serialize = "item/plan/delta",
		serialize = "item/reasoning/summaryPartAdded",
		serialize = "item/reasoning/summaryTextDelta",
		serialize = "item/reasoning/textDelta",
		serialize = "mcpServer/event/stream/notification",
		serialize = "mcpServer/oauthLogin/completed",
		serialize = "mcpServer/startupStatus/updated",
		serialize = "modelProvider/authRecoveryCompleted",
		serialize = "modelProvider/authRecoveryStarted",
		serialize = "model/rerouted",
		serialize = "model/safetyBuffering/updated",
		serialize = "model/verification",
		serialize = "process/exited",
		serialize = "process/outputDelta",
		serialize = "project/changed",
		serialize = "remoteControl/status/changed",
		serialize = "skills/changed",
		serialize = "thread/archived",
		serialize = "thread/attachment/updated",
		serialize = "thread/compacted",
		serialize = "thread/deleted",
		serialize = "thread/environment/connected",
		serialize = "thread/environment/disconnected",
		serialize = "thread/goal/cleared",
		serialize = "thread/goal/updated",
		serialize = "thread/name/updated",
		serialize = "thread/project/updated",
		serialize = "thread/queue/changed",
		serialize = "thread/realtime/closed",
		serialize = "thread/realtime/error",
		serialize = "thread/realtime/itemAdded",
		serialize = "thread/realtime/item/completed",
		serialize = "thread/realtime/item/started",
		serialize = "thread/realtime/item/transcript/delta",
		serialize = "thread/realtime/outputAudio/delta",
		serialize = "thread/realtime/sdp",
		serialize = "thread/realtime/started",
		serialize = "thread/realtime/transcript/delta",
		serialize = "thread/realtime/transcript/done",
		serialize = "thread/reverted",
		serialize = "thread/settings/updated",
		serialize = "thread/started",
		serialize = "thread/status/changed",
		serialize = "thread/unarchived",
		serialize = "turn/diff/updated",
		serialize = "turn/moderationMetadata",
		serialize = "turn/plan/updated",
		serialize = "warning",
		serialize = "windowsSandbox/setupCompleted",
		serialize = "windows/worldWritableWarning"
	)]
	Inert,
	/// Account token refresh request: always refused, never answered with a
	/// token.
	#[strum(serialize = "account/chatgptAuthTokens/refresh", serialize = "attestation/generate")]
	CredentialRequest,
	/// Not a method of the pinned version.
	#[strum(disabled)]
	Unknown,
}

impl Method {
	/// Parses `name`, mapping every unlisted method to [`Method::Unknown`].
	pub(crate) fn parse(name: &str) -> Self {
		name.parse().unwrap_or(Self::Unknown)
	}
}

// ---------------------------------------------------------------------------
// Policy vocabulary
// ---------------------------------------------------------------------------

/// `AskForApproval` as received.
#[derive(Clone, Debug, Deserialize, Eq, PartialEq)]
#[serde(untagged)]
pub(crate) enum ApprovalPolicy {
	/// One of the three plain policies OMP can map.
	Plain(PlainApproval),
	/// The `{granular: …}` object form; never requested, never accepted.
	Granular {
		/// Contents are not interpreted.
		granular: IgnoredAnyEq,
	},
	/// Any other string a newer protocol may add.
	Other(Str),
}

/// The plain approval policies.
#[derive(Clone, Copy, Debug, Deserialize, Eq, PartialEq, Serialize)]
pub(crate) enum PlainApproval {
	/// Ask unless the command is known safe.
	#[serde(rename = "untrusted")]
	Untrusted,
	/// The model decides when to ask.
	#[serde(rename = "on-request")]
	OnRequest,
	/// Never ask.
	#[serde(rename = "never")]
	Never,
}

/// An ignored value that still supports `Eq`/`Clone` for the enclosing enum.
#[derive(Clone, Debug, Eq, PartialEq)]
pub(crate) struct IgnoredAnyEq;

impl<'de> Deserialize<'de> for IgnoredAnyEq {
	fn deserialize<D: serde::Deserializer<'de>>(deserializer: D) -> Result<Self, D::Error> {
		IgnoredAny::deserialize(deserializer).map(|_| Self)
	}
}

impl Serialize for IgnoredAnyEq {
	fn serialize<S: serde::Serializer>(&self, serializer: S) -> Result<S::Ok, S::Error> {
		serializer.serialize_unit()
	}
}

/// Who answers approval requests.
#[derive(Clone, Copy, Debug, Deserialize, Eq, PartialEq, Serialize)]
pub(crate) enum Reviewer {
	/// The client (OMP).
	#[serde(rename = "user")]
	User,
	/// A Codex subagent; never accepted.
	#[serde(rename = "auto_review", alias = "guardian_subagent")]
	AutoReview,
}

/// `SandboxMode` as sent on `thread/start` and `thread/resume`.
#[derive(Clone, Copy, Debug, Deserialize, Eq, PartialEq, Serialize)]
pub(crate) enum SandboxMode {
	/// No writes.
	#[serde(rename = "read-only")]
	ReadOnly,
	/// Writes inside the workspace.
	#[serde(rename = "workspace-write")]
	WorkspaceWrite,
}

/// `SandboxPolicy` as sent on `turn/start` and received in thread responses.
#[derive(Clone, Debug, Deserialize, Eq, PartialEq, Serialize)]
#[serde(tag = "type", rename_all = "camelCase")]
pub(crate) enum SandboxPolicy {
	/// No confinement; received only, never sent.
	DangerFullAccess,
	/// No writes.
	#[serde(rename_all = "camelCase")]
	ReadOnly {
		/// Whether the network is reachable.
		#[serde(default)]
		network_access: bool,
	},
	/// Writes inside the workspace.
	#[serde(rename_all = "camelCase")]
	WorkspaceWrite {
		/// Whether the network is reachable.
		#[serde(default)]
		network_access: bool,
		/// Extra writable roots beyond the working directory.
		#[serde(default)]
		writable_roots: Vec<Str>,
	},
	/// An external sandbox; received only, never sent.
	ExternalSandbox,
	/// A policy kind a newer protocol may add.
	#[serde(other)]
	Unknown,
}

/// The `config` override used to pin network access under workspace-write.
#[derive(Serialize)]
pub(crate) struct ThreadConfig {
	/// `[sandbox_workspace_write]` table.
	pub(crate) sandbox_workspace_write: WorkspaceWriteConfig,
}

/// `[sandbox_workspace_write]`.
#[derive(Serialize)]
pub(crate) struct WorkspaceWriteConfig {
	/// Whether commands may reach the network.
	pub(crate) network_access: bool,
}

