impl<'de> Deserialize<'de> for IgnoredAnyCopy {
	fn deserialize<D: serde::Deserializer<'de>>(deserializer: D) -> Result<Self, D::Error> {
		IgnoredAny::deserialize(deserializer).map(|_| Self)
	}
}

